import { createClient } from 'https://esm.sh/@supabase/supabase-js@2'

// Public, no-login email unsubscribe (GDPR). Reached from a signed link in every
// automated email: /functions/v1/unsubscribe?e=<email>&t=<hmac>. The token is
// HMAC-SHA256(lower(email), SERVICE_ROLE_KEY) — generated by the senders, verified
// here — so a user can opt out WITHOUT an account (the exact gap a deleted user hit).
// Deployed with verify_jwt=false so the email-client GET works with no auth header.
// Supports POST too (RFC 8058 List-Unsubscribe-Post one-click).

const URL_ = Deno.env.get('SUPABASE_URL')!
const SVC  = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!

async function hmacHex(msg: string, secret: string): Promise<string> {
  const key = await crypto.subtle.importKey(
    'raw', new TextEncoder().encode(secret), { name: 'HMAC', hash: 'SHA-256' }, false, ['sign'])
  const sig = await crypto.subtle.sign('HMAC', key, new TextEncoder().encode(msg))
  return [...new Uint8Array(sig)].map((b) => b.toString(16).padStart(2, '0')).join('')
}

function timingSafeEqual(a: string, b: string): boolean {
  if (a.length !== b.length) return false
  let out = 0
  for (let i = 0; i < a.length; i++) out |= a.charCodeAt(i) ^ b.charCodeAt(i)
  return out === 0
}

function page(title: string, body: string, ok = true): Response {
  const accent = ok ? '#00b4d8' : '#ef4444'
  const html = `<!DOCTYPE html><html lang="en"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1"><title>${title} · Badminton 360</title></head>
<body style="margin:0;background:#eef4ff;font-family:-apple-system,Segoe UI,Roboto,Arial,sans-serif;color:#0f172a">
<div style="max-width:480px;margin:0 auto;padding:48px 16px">
  <div style="text-align:center;margin-bottom:18px">
    <div style="font-size:26px;font-weight:800;background:linear-gradient(90deg,#00b4d8,#a855f7);-webkit-background-clip:text;background-clip:text;color:transparent">Badminton 360</div>
  </div>
  <div style="background:#fff;border-radius:18px;padding:30px 24px;box-shadow:0 8px 30px rgba(15,23,42,.08);text-align:center;border-top:4px solid ${accent}">
    ${body}
  </div>
  <p style="text-align:center;color:#94a3b8;font-size:12px;margin-top:16px">
    <a href="https://badminton360.app" style="color:#0891b2">badminton360.app</a> ·
    <a href="mailto:hello@badminton360.app" style="color:#0891b2">hello@badminton360.app</a>
  </p>
</div></body></html>`
  return new Response(html, { status: ok ? 200 : 400, headers: { 'Content-Type': 'text/html; charset=utf-8' } })
}

Deno.serve(async (req) => {
  if (req.method === 'OPTIONS') return new Response('ok')
  try {
    const u = new URL(req.url)
    let email = (u.searchParams.get('e') || '').trim()
    let token = (u.searchParams.get('t') || '').trim()

    // One-click POST (List-Unsubscribe-Post) may send params in the body
    if (req.method === 'POST' && (!email || !token)) {
      try {
        const form = await req.formData()
        email = email || String(form.get('e') || '').trim()
        token = token || String(form.get('t') || '').trim()
      } catch { /* ignore */ }
    }

    if (!email || !token) return page('Invalid link', '<h1 style="font-size:19px;margin:0 0 8px">Invalid unsubscribe link</h1><p style="color:#64748b;font-size:14px">This link is missing information. Please use the Unsubscribe link from a recent email.</p>', false)

    const expected = await hmacHex(email.toLowerCase(), SVC)
    if (!timingSafeEqual(token.toLowerCase(), expected)) {
      return page('Invalid link', '<h1 style="font-size:19px;margin:0 0 8px">This link is no longer valid</h1><p style="color:#64748b;font-size:14px">We couldn\'t verify this unsubscribe link. Please use the Unsubscribe link from a recent email, or email us at hello@badminton360.app.</p>', false)
    }

    const admin = createClient(URL_, SVC)
    const { error } = await admin.rpc('suppress_email', { p_email: email, p_reason: 'user unsubscribe', p_source: 'email-link' })
    if (error) return page('Something went wrong', `<h1 style="font-size:19px;margin:0 0 8px">Something went wrong</h1><p style="color:#64748b;font-size:14px">Please email hello@badminton360.app and we'll remove you right away.</p>`, false)

    return page('Unsubscribed',
      `<h1 style="font-size:20px;margin:0 0 10px">You're unsubscribed ✅</h1>
       <p style="color:#475569;font-size:14px;line-height:1.6;margin:0 0 6px"><b>${email}</b> will no longer receive automated emails from Badminton 360.</p>
       <p style="color:#94a3b8;font-size:13px;margin:14px 0 0">Changed your mind? You can re-enable emails anytime in the app under Settings → Email.</p>`)
  } catch (err) {
    return page('Something went wrong', `<p style="color:#64748b;font-size:14px">${err instanceof Error ? err.message : 'Unknown error'}. Email hello@badminton360.app and we'll remove you.</p>`, false)
  }
})
